/* @lc app=leetcode id=2851 lang=kotlin */
class Solution { fun numberOfWays(s: String, t: String, k: Long): Int = s.length.toLong().let { n -> (t + "#" + s + s.dropLast(1)).let { p -> (1 until p.length).fold(IntArray(p.length)) { pi, i -> pi.apply { pi[i] = (generateSequence(pi[i - 1]) { if (it > 0) pi[it - 1] else null }.firstOrNull { it == null || p[i] == p[it] } ?: 0).let { if (p[i] == p[it]) it + 1 else it } } }.count { it == s.length }.toLong() }.let { m -> kotlin.DeepRecursiveFunction<Pair<Long, Long>, Long> { (a, b) -> if (b == 0L) 1L else (callRecursive(a * a % 1000000007 to b / 2) * (if (b % 2 == 1L) a else 1L)) % 1000000007 }.let { pow -> pow.call(n - 1 to k).let { pK -> pow.call(n to 1000000005L).let { invN -> ((if (k % 2 == 0L) 1L else -1L) * (n - 1)).let { term0 -> ((pK + term0 + 1000000007) % 1000000007 * invN % 1000000007).let { dp0 -> ((pK - (if (k % 2 == 0L) 1L else -1L) + 1000000007) % 1000000007 * invN % 1000000007).let { dpi -> ((if (s == t) (dp0 + (m - 1 + 1000000007) % 1000000007 * dpi) else (m % 1000000007 * dpi)) % 1000000007).toInt() } } } } } } } } }